// Local tabletop workflows. Rules and costs are entered by the player.
function fighterExtra(f){f.advancements??=[];f.injuries??=[];f.loadouts??=[];f.xpHistory??=[];f.ooaRecords??=[];return f}function gameData(){data.gangs.forEach(g=>(g.fighters||[]).forEach(fighterExtra));data.campaigns.forEach(c=>{c.resourceLog??=[];c.captives??=[]})}gameData();
const previousGangPage2=gangPage;gangPage=function(){let html=previousGangPage2();return html.replace('<div class="stats">',`<div class="actions game-actions"><button class="btn small" data-play="dice">주사위</button><button class="btn small" data-play="post-cycle">사이클 종료</button><button class="btn small" data-play="trade">거래소</button></div><div class="stats">`)};
const previousStashTab2=stashTab;stashTab=function(g){let html=previousStashTab2(g);return html.replace('data-action="new-stash"', 'data-action="new-stash"').replace('</div>',`<button class="btn" data-play="trade">거래소</button></div>`)};
const previousFighterDetail2=fighterDetail;fighterDetail=function(f){fighterExtra(f);previousFighterDetail2(f);let pane=document.querySelector('.modal-body');if(!pane)return;let active=f.loadouts.find(l=>l.active);pane.insertAdjacentHTML('beforeend',`<div class="extra-detail"><h3>경험치와 발전</h3><p>경험치 ${fmt(f.xp)} · 발전 ${f.advancements.length}개 · 처치 ${fmt(f.kills)}</p><div class="mini-list">${f.advancements.map(a=>`<div class="mini-row"><span>${esc(a.name)} <small>(${esc(a.kind)})</small></span><button class="btn small danger" data-play="remove-advancement" data-id="${f.id}" data-sub="${a.id}">삭제</button></div>`).join('')||'<span class="muted">발전 없음</span>'}</div><div class="actions"><button class="btn small" data-play="add-xp" data-id="${f.id}">＋ 경험치</button><button class="btn small" data-play="add-advancement" data-id="${f.id}">＋ 발전</button></div><h3>지속 부상</h3><div class="mini-list">${f.injuries.map(a=>`<div class="mini-row"><span>${esc(a.name)}${a.stat&&a.amount?` · ${esc(a.stat)} ${a.amount>0?'+':''}${a.amount}`:''}</span><button class="btn small" data-play="heal-injury" data-id="${f.id}" data-sub="${a.id}">회복</button></div>`).join('')||'<span class="muted">부상 없음</span>'}</div><div class="actions"><button class="btn small" data-play="add-injury" data-id="${f.id}">＋ 부상</button><button class="btn small" data-play="status" data-id="${f.id}">상태 변경</button></div><h3>장비 로드아웃</h3><p>활성: ${esc(active?.name||'지정되지 않음')}</p><div class="mini-list">${f.loadouts.map(l=>`<div class="mini-row"><span>${esc(l.name)} ${l.active?chip('활성','gold'):''} · ${l.equipmentIds.length}개 장비</span><span><button class="btn small" data-play="activate-loadout" data-id="${f.id}" data-sub="${l.id}">활성</button><button class="btn small danger" data-play="delete-loadout" data-id="${f.id}" data-sub="${l.id}">삭제</button></span></div>`).join('')}</div><button class="btn small" data-play="new-loadout" data-id="${f.id}">＋ 로드아웃</button></div>`)};
function addXp(f){let g=gang();const reasons=[['Serious Injury',1],['Out of Action',2],['Leader / Champion / Vehicle',1],['Wreck Vehicle',2],['Assistance',1],['Battle Participation',1],['Controlled Objective',1],['Miscellaneous',1]];formModal(`${esc(f.name)} · 경험치`,select('reason','획득 이유',reasons.map(([x])=>x),reasons[0][0])+field('count','횟수',1,'number','min="1" required')+field('override','직접 지정 XP (선택)','', 'number','min="0"')+textarea('notes','메모'),v=>{let unit=reasons.find(x=>x[0]===v.reason)?.[1]||1,amount=v.override===''?unit*n(v.count):n(v.override);f.xp+=amount;f.xpHistory.unshift({id:id(),at:now(),reason:v.reason,amount,notes:v.notes});log(g,`${f.name}: ${v.reason} +${amount} XP`);save()})}
function addAdvancement(f){let g=gang();formModal(`${esc(f.name)} · 발전`,field('name','발전 이름','','text','required')+select('kind','유형',['Characteristic','Skill','Other'])+select('stat','변경 능력치',[['','없음'],...Object.keys(baseStats).map(k=>[k,k])])+field('amount','능력치 변화',0,'number')+field('xpCost','XP 소모',0,'number','min="0"')+field('cost','평점 비용 증가 (cr)',0,'number','min="0"'),v=>{let xpCost=n(v.xpCost);if(f.xp<xpCost){alert(`XP가 부족합니다. 현재 ${f.xp} XP`);return false}let a={id:id(),name:v.name,kind:v.kind,stat:v.stat,amount:Number(v.amount)||0,xpCost,cost:n(v.cost)};f.xp-=xpCost;f.cost+=a.cost;f.advancements.push(a);if(a.kind==='Skill'&&!f.skills.includes(a.name))f.skills.push(a.name);if(a.stat&&a.amount)f.effects.push({id:id(),name:a.name,category:'Advancement',stat:a.stat,amount:a.amount,advancementId:a.id});log(g,`${f.name}에게 ${a.name} 발전을 추가했습니다.`);save()})}
function addInjury(f){let g=gang();formModal(`${esc(f.name)} · 지속 부상`,field('name','부상 이름','','text','required')+select('stat','능력치 영향',[['','없음'],...Object.keys(baseStats).map(k=>[k,k])])+field('amount','능력치 변화',0,'number')+select('status','파이터 상태',['Active','In Recovery','Captured','Retired','Dead'],f.status)+textarea('notes','부상 메모'),v=>{let a={id:id(),...v,amount:Number(v.amount)||0};f.injuries.push(a);f.status=v.status;if(a.stat&&a.amount)f.effects.push({id:id(),name:a.name,category:'Injury',stat:a.stat,amount:a.amount,injuryId:a.id});log(g,`${f.name}에게 ${a.name} 부상을 기록했습니다.`);save()})}
function newLoadout(f){let checks=f.equipment.map(e=>`<label class="wide"><input type="checkbox" name="equipment" value="${e.id}" style="width:auto"> ${esc(e.name)}</label>`).join('');formModal(`${esc(f.name)} · 로드아웃`,field('name','로드아웃 이름','','text','required')+`<div class="wide"><strong>장비 선택</strong><div class="form">${checks||'<span class="muted">파이터 장비가 없습니다.</span>'}</div></div>`,v=>{let form=$('#modal-form'),equipmentIds=[...form.querySelectorAll('input[name="equipment"]:checked')].map(x=>x.value);f.loadouts.push({id:id(),name:v.name,equipmentIds,active:f.loadouts.length===0});log(gang(),`${f.name}의 ${v.name} 로드아웃을 저장했습니다.`);save()})}
function tradeModal(){ensureAssets();let g=gang();let list=data.customAssets.equipment;showModal('거래소',`<p>사용자 자산의 장비를 구매합니다. 현재 크레딧: <strong class="gold">${fmt(g.credits)}</strong></p><div class="mini-list">${list.map(a=>`<div class="mini-row"><span><strong>${esc(a.name)}</strong><br><small>${esc(a.category||a.equipmentType||'장비')} · ${fmt(a.cost)} cr${a.tradePoints?` · 거래 ${esc(a.tradePoints)}`:''}</small></span><button class="btn small" data-play="buy-equipment" data-id="${a.id}">구매</button></div>`).join('')||'<p>사용자 자산에 장비가 없습니다. 먼저 장비를 만들어 주세요.</p>'}</div><div class="actions" style="margin-top:14px"><button class="btn small" data-play="open-catalog">사용자 장비 관리</button></div>`,'닫기',()=>true)}
function buyEquipment(a){let g=gang();if(g.credits<n(a.cost)){alert('크레딧이 부족합니다.');return}formModal(`${esc(a.name)} 구매`,select('destination','보관 위치',[['stash','갱 창고'],...g.fighters.map(f=>[f.id,f.name])],'stash'),v=>{g.credits-=n(a.cost);let item={id:id(),name:a.name,cost:n(a.cost),presetId:a.id};if(v.destination==='stash')g.stash.push(item);else g.fighters.find(f=>f.id===v.destination)?.equipment.push(item);log(g,`${a.name}을(를) ${fmt(a.cost)} cr에 구매했습니다.`);save()})}
function postCycle(){let g=gang();formModal('사이클 종료',field('income','이번 사이클 수입 (cr)',0,'number','min="0"')+field('expenses','이번 사이클 지출 (cr)',0,'number','min="0"')+field('reputation','명성 변화',0,'number')+select('recover','회복 중 파이터',['아니요','모두 활동 복귀'],'아니요')+textarea('notes','사이클 메모'),v=>{g.credits=Math.max(0,g.credits+n(v.income)-n(v.expenses));g.reputation=Math.max(0,g.reputation+(Number(v.reputation)||0));let count=0;if(v.recover==='모두 활동 복귀')for(let f of g.fighters)if(f.status==='In Recovery'){f.status='Active';count++}log(g,`사이클 종료: +${fmt(v.income)} / -${fmt(v.expenses)} cr, 명성 ${v.reputation||0}, 회복 ${count}명${v.notes?` · ${v.notes}`:''}`);save()})}
function diceRoll(){showModal('주사위',`<div class="form">${select('dice','주사위',['D6','D3','D66'],'D6')}${field('count','개수',1,'number','min="1" max="20"')}</div><div id="dice-result" class="dice-result">굴리기를 누르세요.</div>`,'굴리기',()=>{let type=$('.modal-body select[name="dice"]').value,count=Math.min(20,Math.max(1,Number($('.modal-body input[name="count"]').value)||1)),sides=type==='D3'?3:6;let values=[];for(let i=0;i<count;i++){let a=new Uint32Array(1);crypto.getRandomValues(a);values.push(type==='D66'?`${a[0]%6+1}${(a[0]>>>8)%6+1}`:a[0]%sides+1)}$('#dice-result').textContent=`결과: ${values.join(' · ')}${type==='D66'?'':`  | 합계 ${values.reduce((a,b)=>a+b,0)}`}`;return false})}
const oldMembersTab=membersTab;membersTab=function(c){let html=oldMembersTab(c);let standings=[...c.members].map(m=>{let g=data.gangs.find(x=>x.id===m.gangId);return {name:g?.name||'삭제된 갱',rating:rating(g),reputation:g?.reputation||0,territories:c.territories.filter(t=>t.gangId===m.gangId).length,wins:c.battles.filter(b=>b.winner===m.gangId).length}}).sort((a,b)=>b.rating-a.rating);let captured=c.members.flatMap(m=>{let g=data.gangs.find(x=>x.id===m.gangId);return (g?.fighters||[]).filter(f=>f.status==='Captured').map(f=>({fighter:f,gang:g}))});return html+`<div class="split" style="margin-top:25px"><div class="card"><h3>순위</h3><div class="table-wrap"><table><thead><tr><th>갱</th><th>평점</th><th>명성</th><th>영토</th><th>승리</th></tr></thead><tbody>${standings.map(s=>`<tr><td>${esc(s.name)}</td><td>${fmt(s.rating)}</td><td>${fmt(s.reputation)}</td><td>${s.territories}</td><td>${s.wins}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><h3>포로</h3>${captured.length?captured.map(x=>`<div class="mini-row">${esc(x.fighter.name)} <small>${esc(x.gang.name)}</small></div>`).join(''):'<p class="muted">포로가 없습니다.</p>'}</div></div>`};
const oldBattlesTab2=battlesTab;battlesTab=function(c){let html=oldBattlesTab2(c);let wins=c.members.map(m=>({name:data.gangs.find(g=>g.id===m.gangId)?.name||'삭제된 갱',wins:c.battles.filter(b=>b.winner===m.gangId).length})).sort((a,b)=>b.wins-a.wins);return html+`<div class="card" style="margin-top:25px"><h3>승리 순위</h3>${wins.map((x,i)=>`<div class="mini-row"><span>${i+1}. ${esc(x.name)}</span><strong>${x.wins}승</strong></div>`).join('')||'<p class="muted">참가 갱이 없습니다.</p>'}</div>`};
document.addEventListener('click',e=>{let t=e.target.closest('[data-play]');if(!t)return;e.stopImmediatePropagation();let d=t.dataset,g=gang(),f=g?.fighters?.find(x=>x.id===d.id);if(f)fighterExtra(f);switch(d.play){case 'dice':diceRoll();break;case 'post-cycle':postCycle();break;case 'trade':tradeModal();break;case 'open-catalog':closeModal();data.view='catalog';data.assetTab='equipment';save();break;case 'buy-equipment':{let a=data.customAssets.equipment.find(x=>x.id===d.id);closeModal();buyEquipment(a);break}case 'add-xp':closeModal();addXp(f);break;case 'add-advancement':closeModal();addAdvancement(f);break;case 'remove-advancement':{let a=f.advancements.find(x=>x.id===d.sub);f.advancements=f.advancements.filter(x=>x.id!==d.sub);f.cost=Math.max(0,f.cost-a.cost);f.effects=f.effects.filter(x=>x.advancementId!==a.id);if(a.kind==='Skill')f.skills=f.skills.filter(x=>x!==a.name);closeModal();save();break}case 'add-injury':closeModal();addInjury(f);break;case 'heal-injury':f.injuries=f.injuries.filter(x=>x.id!==d.sub);f.effects=f.effects.filter(x=>x.injuryId!==d.sub);closeModal();log(g,`${f.name}의 부상을 회복했습니다.`);save();break;case 'status':closeModal();formModal('파이터 상태',select('status','상태',['Active','In Recovery','Captured','Retired','Dead','Enslaved','Starved'],f.status),v=>{let old=f.status;f.status=v.status;log(g,`${f.name} 상태: ${old} → ${v.status}`);save()});break;case 'new-loadout':closeModal();newLoadout(f);break;case 'activate-loadout':f.loadouts.forEach(x=>x.active=x.id===d.sub);closeModal();save();break;case 'delete-loadout':f.loadouts=f.loadouts.filter(x=>x.id!==d.sub);closeModal();save();break}},true);
render();
const beforeThemeRender=render;render=function(){beforeThemeRender();document.documentElement?.classList?.toggle('light',data.theme==='light');let actions=document.querySelector('.top-actions');if(actions)actions.insertAdjacentHTML('afterbegin',`<button class="btn small ghost" data-theme-toggle aria-label="테마 전환">${data.theme==='light'?'☾':'☀'}</button>`)};
document.addEventListener('click',e=>{if(!e.target.closest('[data-theme-toggle]'))return;e.stopImmediatePropagation();data.theme=data.theme==='light'?'dark':'light';save()},true);
render();
// Edition, gang subtype, campaign type and authorised trading posts.
editGang=function(g){ensureAssets();let allFactions=[...new Set([...factions,...data.customAssets.gangTypes.map(x=>x.name)])];formModal(g?'갱 수정':'새 갱 만들기',field('name','갱 이름',g?.name,'text','required')+select('faction','갱 유형',allFactions,g?.faction||allFactions[0])+field('subtype','갱 하위 유형',g?.subtype||'')+select('edition','에디션',['N23','N26','Custom'],g?.edition||'N23')+select('alignment','성향',['Law Abiding','Outlaw','Neutral'],g?.alignment||'Law Abiding')+field('credits',g?'크레딧':'시작 크레딧',g?.credits??1000,'number','min="0"')+field('reputation','명성',g?.reputation??0,'number','min="0"')+textarea('notes','갱 메모',g?.notes),v=>{if(g){Object.assign(g,{name:v.name,faction:v.faction,subtype:v.subtype,edition:v.edition,alignment:v.alignment,credits:n(v.credits),reputation:n(v.reputation),notes:v.notes});log(g,'갱 정보를 수정했습니다.')}else{g={id:id(),name:v.name,faction:v.faction,subtype:v.subtype,edition:v.edition,alignment:v.alignment,credits:n(v.credits),reputation:n(v.reputation),meat:0,exploration:0,notes:v.notes,stash:[],fighters:[],vehicles:[],tactics:[],logs:[]};data.gangs.push(g);data.selectedGang=g.id;data.view='gang';data.tab='fighters';log(g,'갱을 만들었습니다.')}save()})};
const priorGangCard=gangCard;gangCard=function(g){let html=priorGangCard(g);return g.subtype?html.replace(`<h3>${esc(g.name)}</h3>`,`<h3>${esc(g.name)}</h3><small class="muted">${esc(g.subtype)}</small>`):html};
gangsPage=function(){let selected=data.editionFilter||'All',list=selected==='All'?data.gangs:data.gangs.filter(g=>g.edition===selected);return heading('GANG ROSTER','나의 갱','갱 자원, 파이터, 무기와 이력을 관리하세요.',btn('＋ 새 갱','new-gang','primary'))+`<div class="edition-filters">${['All','N23','N26'].map(x=>`<button class="btn small ${selected===x?'primary':''}" data-edition-filter="${x}">${x==='All'?'전체':x}</button>`).join('')}</div>`+(list.length?`<div class="grid">${list.map(gangCard).join('')}</div>`:empty('⚔','갱이 없습니다','이 에디션의 갱을 만들어 시작하세요.',btn('갱 만들기','new-gang','primary')))};
editCampaign=function(c){ensureAssets();let posts=data.customAssets.tradingPosts;let postChecks=posts.map(p=>`<label class="wide"><input type="checkbox" name="post" value="${p.id}" ${c?.tradingPosts?.includes(p.id)?'checked':''} style="width:auto"> ${esc(p.name)}</label>`).join('');formModal(c?'캠페인 수정':'새 캠페인 만들기',field('name','캠페인 이름',c?.name,'text','required')+select('edition','에디션',['N23','N26','Custom'],c?.edition||'N23')+field('campaignType','캠페인 유형',c?.campaignType||'Core Campaign')+select('phase','상태',['준비 중','진행 중','종료'],c?.phase||'준비 중')+textarea('description','설명',c?.description)+`<div class="wide"><strong>허용 거래소</strong><div class="form">${postChecks||'<span class="muted">사용자 거래소가 없습니다.</span>'}</div></div>`+textarea('notes','캠페인 메모',c?.notes),v=>{let tradingPosts=[...$('#modal-form').querySelectorAll('input[name="post"]:checked')].map(x=>x.value),value={...v,tradingPosts};if(c)Object.assign(c,value);else{c={id:id(),...value,members:[],territories:[],battles:[],sessions:[],triumphs:[]};data.campaigns.push(c);data.selectedCampaign=c.id;data.view='campaign'}save()})};
document.addEventListener('click',e=>{let t=e.target.closest('[data-edition-filter]');if(!t)return;e.stopImmediatePropagation();data.editionFilter=t.dataset.editionFilter;save()},true);
render();
function campaignResourceSection(c){c.resources??=[];return `<div class="card" style="margin-top:24px"><div class="toolbar"><h3>캠페인 자원</h3><button class="btn small" data-campaign-resource="new">＋ 자원 추가</button></div>${c.resources.length?`<div class="mini-list">${c.resources.map(r=>`<div class="mini-row"><span>${esc(r.name)} <small>${esc(data.gangs.find(g=>g.id===r.gangId)?.name||'캠페인 공용')}</small></span><span><strong>${fmt(r.amount)}</strong> <button class="btn small" data-campaign-resource="edit" data-id="${r.id}">수정</button><button class="btn small danger" data-campaign-resource="delete" data-id="${r.id}">삭제</button></span></div>`).join('')}</div>`:'<p class="muted">등록된 캠페인 자원이 없습니다.</p>'}</div>`}
const previousMembersTab3=membersTab;membersTab=function(c){return previousMembersTab3(c)+campaignResourceSection(c)};
function campaignResourceForm(r){let c=campaign();c.resources??=[];formModal(r?'캠페인 자원 수정':'캠페인 자원 추가',field('name','자원 이름',r?.name,'text','required')+field('amount','수량',r?.amount??0,'number','min="0"')+select('gangId','소유 갱',gangOptions('',true),r?.gangId||''),v=>{if(r)Object.assign(r,{name:v.name,amount:n(v.amount),gangId:v.gangId});else c.resources.push({id:id(),name:v.name,amount:n(v.amount),gangId:v.gangId});save()})}
newBattle=function(){let c=campaign();formModal('전투 보고',field('name','시나리오 / 전투 이름','','text','required')+field('date','날짜',new Date().toISOString().slice(0,10),'date','required')+field('cycle','사이클','')+select('attacker','참가 갱 A',gangOptions('',true))+select('defender','참가 갱 B',gangOptions('',true))+select('winner','승리 갱',gangOptions('',true))+field('result','결과 / 점수','')+textarea('notes','전투 보고'),v=>{c.battles.push({id:id(),...v});save()})};
const previousCampaignPage3=campaignPage;campaignPage=function(){let html=previousCampaignPage3();return data.view==='campaign'?html.replace('<div class="stats">',`<div class="actions game-actions"><button class="btn small" data-export-campaign="json">JSON 내보내기</button><button class="btn small" data-export-campaign="xml">XML 내보내기</button></div><div class="stats">`):html};
function downloadCampaign(format){let c=campaign(),payload={campaign_name:c.name,edition:c.edition,phase:c.phase,members:c.members.map(m=>{let g=data.gangs.find(x=>x.id===m.gangId);return {player:m.player,role:m.role,gang:g?{id:g.id,name:g.name,rating:rating(g),wealth:g.credits,territories:c.territories.filter(t=>t.gangId===g.id).map(t=>t.name)}:null}}),battles:c.battles,territories:c.territories.map(t=>({name:t.name,gangId:t.gangId}))};let xmlEsc=x=>String(x??'').replace(/[<>&"']/g,ch=>({'<':'&lt;','>':'&gt;','&':'&amp;','"':'&quot;',"'":'&apos;'}[ch]));let toXml=(name,value)=>Array.isArray(value)?value.map(x=>toXml(({members:'member',battles:'battle',territories:'territory'}[name]||'item'),x)).join(''):value&&typeof value==='object'?`<${name}>${Object.entries(value).map(([k,v])=>toXml(k,v)).join('')}</${name}>`:`<${name}>${xmlEsc(value)}</${name}>`;let content=format==='xml'?`<?xml version="1.0" encoding="UTF-8"?>\n${toXml('campaign_data',payload)}`:JSON.stringify(payload,null,2),type=format==='xml'?'application/xml':'application/json',blob=new Blob([content],{type});let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download=`campaign-${c.name.replace(/[^a-zA-Z0-9가-힣_-]/g,'_')}.${format}`;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
document.addEventListener('click',e=>{let t=e.target.closest('[data-campaign-resource],[data-export-campaign]');if(!t)return;e.stopImmediatePropagation();let d=t.dataset,c=campaign();if(d.exportCampaign){downloadCampaign(d.exportCampaign);return}c.resources??=[];let r=c.resources.find(x=>x.id===d.id);if(d.campaignResource==='new')campaignResourceForm();else if(d.campaignResource==='edit')campaignResourceForm(r);else if(d.campaignResource==='delete')confirmDelete('자원 삭제',`${esc(r.name)}을(를) 삭제할까요?`,()=>{c.resources=c.resources.filter(x=>x.id!==r.id);save()})},true);
render();
